    /// </summary>
    /// <param name="values">
    ///    The elements to add.
    /// </param>
    public async Task AddToAvailableCreateTools(params AvailableCreateTool[] values)
    {
        AvailableCreateTool[] join = AvailableCreateTools is null
            ? values
            : [..AvailableCreateTools, ..values];
        await SetAvailableCreateTools(join);
    }
    
